test(`V2 Genesis ${GENESIS_CAPACITY_COUNT||'capacity'} records完整seed/batch deterministic容量`,{skip:GENESIS_CAPACITY_COUNT===0},()=>{
 const total=GENESIS_CAPACITY_COUNT,encoder=new TextEncoder(),reorderMap=value=>Array.isArray(value)?value.map(reorderMap):value&&typeof value==='object'?Object.fromEntries(Object.entries(value).reverse().map(([key,entry])=>[key,reorderMap(entry)])):value;
 const documents=(reverse=false,reorder=false)=>{const docs=empty();docs.students=Array.from({length:total},(_,position)=>{const index=reverse?total-1-position:position,id='student-'+String(index).padStart(8,'0'),row=raw('students',id,{id,name:'N'+index,nested:{alpha:index,omega:'容量'}});if(reorder)row.data=reorderMap(row.data);return row});return docs};
 let source=fixture(documents()),execution=build(source),payload=consume(execution);
 const expectedBatchCount=Math.ceil(total/RECORD_SYNC_V2_GENESIS_MAX_BATCH_RECORDS),proof={manifest:structuredClone(execution.manifest),batchReceipts:structuredClone(execution.batchReceipts)};
 const records=payload.recordsByCollection.students;
 assert.equal(execution.recordCount,total);assert.equal(execution.batchCount,expectedBatchCount);assert.equal(execution.manifest.documentCount,total);assert.equal(execution.manifest.activeCount,total);assert.equal(execution.manifest.tombstoneCount,0);assert.equal(execution.manifest.auditedCount,total);assert.equal(execution.manifest.unauditedCount,0);assert.equal(records.length,total);assert.equal(new Set(records.map(row=>row.genesisRecordHash)).size,total);assert.ok(records.every(row=>row.schema===RECORD_SYNC_V2_GENESIS_RECORD_SCHEMA&&row.revision===1&&!row.deleted));assert.equal(payload.batches.length,expectedBatchCount);assert.equal(payload.batches.reduce((sum,batch)=>sum+batch.recordCount,0),total);assert.ok(payload.batches.every(batch=>batch.recordCount>=1&&batch.recordCount<=RECORD_SYNC_V2_GENESIS_MAX_BATCH_RECORDS));
 for(let index=0;index<payload.batches.length;index++)assert.ok(encoder.encode(JSON.stringify(payload.batches[index])).length+encoder.encode(JSON.stringify(execution.batchReceipts[index])).length<RECORD_SYNC_V2_GENESIS_MAX_BATCH_CANONICAL_BYTES);
 source=null;execution=null;payload=null;global.gc?.();
 source=fixture(documents(true,true));execution=build(source);payload=consume(execution);
 assert.equal(execution.recordCount,total);assert.equal(execution.batchCount,expectedBatchCount);assert.deepEqual(execution.manifest,proof.manifest);assert.deepEqual(execution.batchReceipts,proof.batchReceipts);assert.equal(payload.recordsByCollection.students.length,total);assert.equal(payload.batches.reduce((sum,batch)=>sum+batch.recordCount,0),total);
});

